/* Bundle a self-contained worker for offline file:// and WKWebView use. */
'use strict';
const fs = require('node:fs');
const path = require('node:path');
const source = ['engine.js','coach.js','coach-worker.js'].map(name => fs.readFileSync(path.join(__dirname,name),'utf8')).join('\n;\n');
fs.writeFileSync(path.join(__dirname,'coach-worker-source.js'),
  '/* Generated by build-coach-worker.js. Keep in sync with engine/coach sources. */\n'+
  'globalThis.PIXEL_COACH_WORKER_SOURCE = '+JSON.stringify(source)+';\n');
console.log('离线教练已打包：'+Buffer.byteLength(source).toLocaleString('en-US')+' bytes');
